-- Karachi Transit: all migrations + demo seed, in order.
-- DEMO / SIMULATED HACKATHON DATA. Generated by scripts/build-apply-all.mjs.
-- Paste into the Supabase SQL editor and run once.


-- ===== supabase/migrations/20261001120000_core_schema.sql =====
-- =============================================================================
-- Smart Public Transport & Bus Tracking Platform - Karachi
-- Migration 1/3: core relational schema
--
-- DEMO / SIMULATED DATA NOTICE
-- This schema is built for a hackathon demonstration. Route names, stop
-- groupings, schedules, fares, bus registrations and driver records that are
-- loaded by supabase/seed.sql are INVENTED for the demo. Stop coordinates point
-- at real, well-known Karachi landmarks so the map looks plausible, but no part
-- of this dataset should be presented as the actual Karachi public transport
-- network. See docs/ASSUMPTIONS.md.
--
-- All timestamps are timestamptz (stored UTC). Karachi is UTC+05:00 with no
-- daylight saving; render with `AT TIME ZONE 'Asia/Karachi'` in the UI.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
create type public.user_role as enum ('passenger', 'driver', 'operator', 'admin');

create type public.driver_status as enum ('active', 'off_duty', 'on_leave');

create type public.bus_status as enum ('active', 'idle', 'maintenance', 'offline');

create type public.trip_status as enum ('scheduled', 'in_progress', 'completed', 'cancelled');

create type public.trip_direction as enum ('outbound', 'inbound');

create type public.stop_arrival_status as enum ('pending', 'arrived', 'skipped');

create type public.alert_severity as enum ('info', 'warning', 'critical');

-- -----------------------------------------------------------------------------
-- Shared trigger: keep updated_at fresh
-- -----------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- profiles
-- auth_user_id is nullable on purpose: demo rows are seeded without creating
-- Supabase auth users. Real sign-ups link themselves by setting auth_user_id.
-- -----------------------------------------------------------------------------
create table public.profiles (
  id            uuid primary key default gen_random_uuid(),
  auth_user_id  uuid unique,
  full_name     text not null,
  email         text unique,
  phone         text,
  role          public.user_role not null default 'passenger',
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

comment on table public.profiles is
  'Application users. auth_user_id links to auth.users(id) once a real account exists; demo rows leave it null.';

create index profiles_role_idx on public.profiles (role);

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- drivers
-- -----------------------------------------------------------------------------
create table public.drivers (
  id          uuid primary key default gen_random_uuid(),
  profile_id  uuid unique references public.profiles (id) on delete set null,
  full_name   text not null,
  license_no  text not null unique,
  phone       text,
  status      public.driver_status not null default 'off_duty',
  rating      numeric(2, 1) check (rating between 0 and 5),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

comment on table public.drivers is 'Bus drivers. Demo licence numbers are fabricated (DEMO-LIC-*).';

create index drivers_status_idx on public.drivers (status);

create trigger drivers_set_updated_at
  before update on public.drivers
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- buses
-- -----------------------------------------------------------------------------
create table public.buses (
  id                 uuid primary key default gen_random_uuid(),
  registration_no    text not null unique,
  label              text,
  model              text,
  capacity           integer not null default 45 check (capacity > 0),
  has_ac             boolean not null default false,
  status             public.bus_status not null default 'offline',
  assigned_driver_id uuid references public.drivers (id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

comment on table public.buses is
  'Fleet vehicles. status is the live vehicle state: active (running a trip), idle (available), maintenance, offline (no telemetry).';

create index buses_status_idx on public.buses (status);

create trigger buses_set_updated_at
  before update on public.buses
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- routes
-- -----------------------------------------------------------------------------
create table public.routes (
  id                   uuid primary key default gen_random_uuid(),
  code                 text not null unique,
  name                 text not null,
  description          text,
  color                text not null default '#2563eb' check (color ~ '^#[0-9A-Fa-f]{6}$'),
  distance_km          numeric(6, 2) not null check (distance_km > 0),
  avg_speed_kmh        numeric(5, 2) not null default 18 check (avg_speed_kmh > 0),
  expected_duration_min integer not null check (expected_duration_min > 0),
  fare_pkr             numeric(7, 2) not null default 50 check (fare_pkr >= 0),
  headway_min          integer not null default 20 check (headway_min > 0),
  first_departure      time,
  last_departure       time,
  is_active            boolean not null default true,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

comment on table public.routes is
  'Demo bus corridors. avg_speed_kmh is the planning speed used by the deterministic ETA fallback.';

create trigger routes_set_updated_at
  before update on public.routes
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- stops
-- -----------------------------------------------------------------------------
create table public.stops (
  id         uuid primary key default gen_random_uuid(),
  code       text not null unique,
  name       text not null,
  area       text,
  latitude   numeric(9, 6) not null check (latitude between -90 and 90),
  longitude  numeric(9, 6) not null check (longitude between -180 and 180),
  is_active  boolean not null default true,
  created_at timestamptz not null default now()
);

comment on table public.stops is
  'Physical stop locations. Coordinates are approximate positions of real Karachi landmarks; the stops themselves are demo constructs.';

create index stops_lat_lon_idx on public.stops (latitude, longitude);

-- -----------------------------------------------------------------------------
-- route_stops: ordered sequence of stops per route and direction
-- -----------------------------------------------------------------------------
create table public.route_stops (
  id                     uuid primary key default gen_random_uuid(),
  route_id               uuid not null references public.routes (id) on delete cascade,
  stop_id                uuid not null references public.stops (id) on delete restrict,
  direction              public.trip_direction not null default 'outbound',
  stop_order             integer not null check (stop_order > 0),
  distance_from_start_km numeric(6, 2) not null default 0 check (distance_from_start_km >= 0),
  scheduled_offset_min   integer not null default 0 check (scheduled_offset_min >= 0),
  is_major_stop          boolean not null default false,
  constraint route_stops_unique_order unique (route_id, direction, stop_order),
  constraint route_stops_unique_stop  unique (route_id, direction, stop_id)
);

comment on table public.route_stops is
  'Route -> stop ordering. distance_from_start_km drives distance-based ETA; scheduled_offset_min is minutes after trip start for the timetable.';

create index route_stops_route_dir_order_idx on public.route_stops (route_id, direction, stop_order);
create index route_stops_stop_idx on public.route_stops (stop_id);

-- -----------------------------------------------------------------------------
-- trips: one bus running one route in one direction at a point in time
-- -----------------------------------------------------------------------------
create table public.trips (
  id                 uuid primary key default gen_random_uuid(),
  trip_code          text not null unique,
  route_id           uuid not null references public.routes (id) on delete cascade,
  bus_id             uuid not null references public.buses (id) on delete restrict,
  driver_id          uuid references public.drivers (id) on delete set null,
  direction          public.trip_direction not null default 'outbound',
  service_date       date not null default current_date,
  scheduled_start_at timestamptz not null,
  scheduled_end_at   timestamptz not null,
  actual_start_at    timestamptz,
  actual_end_at      timestamptz,
  status             public.trip_status not null default 'scheduled',
  delay_minutes      integer not null default 0,
  progress_km        numeric(6, 2) not null default 0 check (progress_km >= 0),
  last_stop_order    integer check (last_stop_order >= 0),
  next_stop_id       uuid references public.stops (id) on delete set null,
  occupancy          integer not null default 0 check (occupancy >= 0),
  notes              text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint trips_schedule_order check (scheduled_end_at > scheduled_start_at)
);

comment on table public.trips is
  'A scheduled or running service. delay_minutes is positive when late, negative when early. progress_km is distance covered from the route origin.';

create index trips_status_idx on public.trips (status);
create index trips_route_idx on public.trips (route_id, service_date);
create index trips_bus_idx on public.trips (bus_id, service_date);

create trigger trips_set_updated_at
  before update on public.trips
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- bus_locations: GPS history (the "trip_locations" equivalent)
-- trip_id is nullable so a parked/idle bus can still report a last known fix.
-- -----------------------------------------------------------------------------
create table public.bus_locations (
  id          bigint generated always as identity primary key,
  bus_id      uuid not null references public.buses (id) on delete cascade,
  trip_id     uuid references public.trips (id) on delete set null,
  recorded_at timestamptz not null default now(),
  latitude    numeric(9, 6) not null check (latitude between -90 and 90),
  longitude   numeric(9, 6) not null check (longitude between -180 and 180),
  speed_kmh   numeric(5, 2) not null default 0 check (speed_kmh >= 0),
  heading_deg numeric(5, 2) check (heading_deg >= 0 and heading_deg < 360),
  progress_km numeric(6, 2) check (progress_km >= 0),
  source      text not null default 'simulated' check (source in ('simulated', 'device', 'manual'))
);

comment on table public.bus_locations is
  'Append-only location history for every bus. Latest row per bus is exposed by v_bus_latest_location.';

create index bus_locations_bus_recorded_idx on public.bus_locations (bus_id, recorded_at desc);
create index bus_locations_trip_recorded_idx on public.bus_locations (trip_id, recorded_at desc);

-- -----------------------------------------------------------------------------
-- trip_stop_times: scheduled vs estimated vs actual arrival per stop
-- stop_id is denormalised from route_stops to keep passenger queries cheap.
-- -----------------------------------------------------------------------------
create table public.trip_stop_times (
  id                   uuid primary key default gen_random_uuid(),
  trip_id              uuid not null references public.trips (id) on delete cascade,
  route_stop_id        uuid not null references public.route_stops (id) on delete cascade,
  stop_id              uuid not null references public.stops (id) on delete restrict,
  stop_order           integer not null check (stop_order > 0),
  scheduled_arrival_at timestamptz not null,
  estimated_arrival_at timestamptz,
  actual_arrival_at    timestamptz,
  status               public.stop_arrival_status not null default 'pending',
  constraint trip_stop_times_unique unique (trip_id, route_stop_id)
);

comment on table public.trip_stop_times is
  'Per-stop timetable for a trip. Persisted snapshot; v_trip_stop_eta recomputes live estimates deterministically.';

create index trip_stop_times_trip_order_idx on public.trip_stop_times (trip_id, stop_order);
create index trip_stop_times_stop_idx on public.trip_stop_times (stop_id);

-- -----------------------------------------------------------------------------
-- service_alerts
-- -----------------------------------------------------------------------------
create table public.service_alerts (
  id         uuid primary key default gen_random_uuid(),
  title      text not null,
  message    text not null,
  severity   public.alert_severity not null default 'info',
  route_id   uuid references public.routes (id) on delete cascade,
  bus_id     uuid references public.buses (id) on delete cascade,
  stop_id    uuid references public.stops (id) on delete cascade,
  starts_at  timestamptz not null default now(),
  ends_at    timestamptz,
  is_active  boolean not null default true,
  created_at timestamptz not null default now(),
  constraint service_alerts_window check (ends_at is null or ends_at > starts_at)
);

comment on table public.service_alerts is
  'Operator notices. route_id / bus_id / stop_id are all optional so an alert can be network-wide or narrowly scoped.';

create index service_alerts_active_idx on public.service_alerts (is_active, starts_at desc);


-- ===== supabase/migrations/20261001120100_functions_and_views.sql =====
-- =============================================================================
-- Smart Public Transport & Bus Tracking Platform - Karachi
-- Migration 2/3: helper functions and read views
--
-- No machine learning anywhere. Every estimate here is a deterministic
-- arithmetic calculation over route geometry, timetable offsets, reported
-- speed and recorded delay. The formula is documented in docs/DATA_MODEL.md.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- fn_haversine_km: great-circle distance in kilometres.
-- Avoids a PostGIS dependency, which keeps the hackathon setup to plain SQL.
-- -----------------------------------------------------------------------------
create or replace function public.fn_haversine_km(
  p_lat1 numeric,
  p_lon1 numeric,
  p_lat2 numeric,
  p_lon2 numeric
) returns numeric
language sql
immutable
as $$
  select round(
    (6371.0088 * 2 * asin(
      sqrt(
        power(sin(radians(p_lat2::double precision - p_lat1::double precision) / 2), 2)
        + cos(radians(p_lat1::double precision))
        * cos(radians(p_lat2::double precision))
        * power(sin(radians(p_lon2::double precision - p_lon1::double precision) / 2), 2)
      )
    ))::numeric,
    3
  );
$$;

comment on function public.fn_haversine_km is
  'Great-circle distance in km between two lat/lon pairs. Straight-line, not road distance.';

-- -----------------------------------------------------------------------------
-- fn_route_segments: consecutive stop pairs of a route direction.
-- Used to interpolate a position at an arbitrary distance along the route.
-- -----------------------------------------------------------------------------
create or replace function public.fn_route_segments(
  p_route_id uuid,
  p_direction public.trip_direction
) returns table (
  stop_order integer,
  km0 numeric,
  lat0 numeric,
  lon0 numeric,
  km1 numeric,
  lat1 numeric,
  lon1 numeric
)
language sql
stable
as $$
  select *
  from (
    select
      rs.stop_order,
      rs.distance_from_start_km as km0,
      s.latitude  as lat0,
      s.longitude as lon0,
      lead(rs.distance_from_start_km) over w as km1,
      lead(s.latitude)  over w as lat1,
      lead(s.longitude) over w as lon1
    from public.route_stops rs
    join public.stops s on s.id = rs.stop_id
    where rs.route_id = p_route_id
      and rs.direction = p_direction
    window w as (order by rs.stop_order)
  ) seg
  where seg.km1 is not null;
$$;

-- -----------------------------------------------------------------------------
-- fn_route_point_at_km: linear interpolation of a point along a route.
-- Straight lines between consecutive stops - good enough for a demo map and
-- for generating plausible seed telemetry. Not road-snapped.
-- -----------------------------------------------------------------------------
create or replace function public.fn_route_point_at_km(
  p_route_id uuid,
  p_direction public.trip_direction,
  p_km numeric
) returns table (
  latitude    numeric,
  longitude   numeric,
  heading_deg numeric
)
language plpgsql
stable
as $$
declare
  v_seg     record;
  v_km      numeric := greatest(coalesce(p_km, 0), 0);
  v_ratio   numeric;
  v_bearing double precision;
begin
  select * into v_seg
  from public.fn_route_segments(p_route_id, p_direction) s
  where s.km0 <= v_km
  order by s.km0 desc
  limit 1;

  if not found then
    select * into v_seg
    from public.fn_route_segments(p_route_id, p_direction) s
    order by s.km0 asc
    limit 1;
  end if;

  if not found then
    return;
  end if;

  v_ratio := case
    when v_seg.km1 = v_seg.km0 then 0
    else least(greatest((v_km - v_seg.km0) / (v_seg.km1 - v_seg.km0), 0), 1)
  end;

  v_bearing := degrees(
    atan2(
      sin(radians(v_seg.lon1::double precision - v_seg.lon0::double precision))
        * cos(radians(v_seg.lat1::double precision)),
      cos(radians(v_seg.lat0::double precision)) * sin(radians(v_seg.lat1::double precision))
        - sin(radians(v_seg.lat0::double precision)) * cos(radians(v_seg.lat1::double precision))
          * cos(radians(v_seg.lon1::double precision - v_seg.lon0::double precision))
    )
  );
  v_bearing := v_bearing - floor(v_bearing / 360.0) * 360.0;

  latitude    := round(v_seg.lat0 + (v_seg.lat1 - v_seg.lat0) * v_ratio, 6);
  longitude   := round(v_seg.lon0 + (v_seg.lon1 - v_seg.lon0) * v_ratio, 6);
  heading_deg := round(v_bearing::numeric, 2);

  if heading_deg >= 360 then
    heading_deg := 0;
  end if;

  return next;
end;
$$;

comment on function public.fn_route_point_at_km is
  'Interpolated lat/lon/bearing at a given distance along a route direction. Straight-line between stops, not road-snapped.';

-- -----------------------------------------------------------------------------
-- v_bus_latest_location: newest fix per bus.
-- -----------------------------------------------------------------------------
create or replace view public.v_bus_latest_location as
select distinct on (bl.bus_id)
  bl.bus_id,
  bl.trip_id,
  bl.recorded_at,
  bl.latitude,
  bl.longitude,
  bl.speed_kmh,
  bl.heading_deg,
  bl.progress_km,
  bl.source,
  (now() - bl.recorded_at) as location_age
from public.bus_locations bl
order by bl.bus_id, bl.recorded_at desc;

comment on view public.v_bus_latest_location is 'Most recent location row for each bus.';

-- -----------------------------------------------------------------------------
-- v_fleet_status: one row per bus for the operator monitoring screen.
-- -----------------------------------------------------------------------------
create or replace view public.v_fleet_status as
select
  b.id as bus_id,
  b.registration_no,
  b.label as bus_label,
  b.status as bus_status,
  b.capacity,
  d.id   as driver_id,
  d.full_name as driver_name,
  t.id   as trip_id,
  t.trip_code,
  t.status as trip_status,
  r.id   as route_id,
  r.code as route_code,
  r.name as route_name,
  r.color as route_color,
  t.delay_minutes,
  coalesce(t.delay_minutes, 0) >= 5 as is_delayed,
  t.progress_km,
  l.latitude,
  l.longitude,
  l.speed_kmh,
  l.heading_deg,
  l.recorded_at as location_recorded_at,
  l.location_age,
  (l.recorded_at is null or l.recorded_at < now() - interval '10 minutes') as telemetry_stale
from public.buses b
left join public.drivers d on d.id = b.assigned_driver_id
left join public.trips t on t.bus_id = b.id and t.status = 'in_progress'
left join public.routes r on r.id = t.route_id
left join public.v_bus_latest_location l on l.bus_id = b.id;

comment on view public.v_fleet_status is
  'One row per bus with its live trip (if any), latest fix and a telemetry_stale flag for offline detection.';

-- -----------------------------------------------------------------------------
-- v_active_trips: everything the live map needs for currently running trips.
-- -----------------------------------------------------------------------------
create or replace view public.v_active_trips as
select
  t.id as trip_id,
  t.trip_code,
  t.status,
  t.direction,
  t.service_date,
  t.scheduled_start_at,
  t.scheduled_end_at,
  t.actual_start_at,
  t.delay_minutes,
  (t.delay_minutes >= 5) as is_delayed,
  t.progress_km,
  t.last_stop_order,
  t.occupancy,
  r.id as route_id,
  r.code as route_code,
  r.name as route_name,
  r.color as route_color,
  r.distance_km as route_distance_km,
  r.fare_pkr,
  case
    when r.distance_km > 0 then round(100 * t.progress_km / r.distance_km, 1)
    else 0
  end as progress_pct,
  b.id as bus_id,
  b.registration_no,
  b.label as bus_label,
  b.capacity,
  case
    when b.capacity > 0 then round(100.0 * t.occupancy / b.capacity, 1)
    else 0
  end as occupancy_pct,
  d.id as driver_id,
  d.full_name as driver_name,
  d.phone as driver_phone,
  ns.id as next_stop_id,
  ns.name as next_stop_name,
  l.latitude,
  l.longitude,
  l.speed_kmh,
  l.heading_deg,
  l.recorded_at as location_recorded_at
from public.trips t
join public.routes r on r.id = t.route_id
join public.buses b on b.id = t.bus_id
left join public.drivers d on d.id = t.driver_id
left join public.stops ns on ns.id = t.next_stop_id
left join public.v_bus_latest_location l on l.bus_id = t.bus_id
where t.status = 'in_progress';

comment on view public.v_active_trips is 'Live trips joined to route, bus, driver, next stop and latest GPS fix.';

-- -----------------------------------------------------------------------------
-- v_trip_stop_eta: deterministic ETA for every upcoming stop of a live trip.
--
--   remaining_km = max(stop_distance_from_start - trip_progress, 0)
--   speed        = latest non-zero reported speed, else route planning speed
--   travel_min   = remaining_km / speed * 60
--   dwell_min    = 0.5 min per intermediate stop still to be served
--   eta_minutes  = ceil(travel_min + dwell_min)
-- -----------------------------------------------------------------------------
create or replace view public.v_trip_stop_eta as
select
  c.trip_id,
  c.trip_code,
  c.route_id,
  c.route_code,
  c.direction,
  c.stop_id,
  c.stop_code,
  c.stop_name,
  c.stop_order,
  c.latitude,
  c.longitude,
  c.distance_from_start_km,
  c.remaining_km,
  c.effective_speed_kmh,
  c.stops_ahead,
  c.eta_minutes,
  (now() + (c.eta_minutes * interval '1 minute')) as estimated_arrival_at,
  c.scheduled_arrival_at,
  round(
    extract(epoch from (now() + (c.eta_minutes * interval '1 minute')) - c.scheduled_arrival_at) / 60.0
  )::integer as projected_delay_minutes
from (
  select
    live.trip_id,
    live.trip_code,
    live.route_id,
    live.route_code,
    live.direction,
    s.id   as stop_id,
    s.code as stop_code,
    s.name as stop_name,
    s.latitude,
    s.longitude,
    rs.stop_order,
    rs.distance_from_start_km,
    greatest(rs.distance_from_start_km - live.progress_km, 0) as remaining_km,
    live.effective_speed_kmh,
    (rs.stop_order - coalesce(live.last_stop_order, 0)) as stops_ahead,
    ceil(
      (greatest(rs.distance_from_start_km - live.progress_km, 0) / live.effective_speed_kmh) * 60
      + greatest(rs.stop_order - coalesce(live.last_stop_order, 0) - 1, 0) * 0.5
    )::integer as eta_minutes,
    live.scheduled_start_at + (rs.scheduled_offset_min * interval '1 minute') as scheduled_arrival_at
  from (
    select
      t.id as trip_id,
      t.trip_code,
      t.route_id,
      t.direction,
      t.progress_km,
      t.last_stop_order,
      t.scheduled_start_at,
      r.code as route_code,
      coalesce(nullif(l.speed_kmh, 0), r.avg_speed_kmh) as effective_speed_kmh
    from public.trips t
    join public.routes r on r.id = t.route_id
    left join public.v_bus_latest_location l on l.bus_id = t.bus_id
    where t.status = 'in_progress'
  ) live
  join public.route_stops rs
    on rs.route_id = live.route_id
   and rs.direction = live.direction
   and rs.stop_order > coalesce(live.last_stop_order, 0)
  join public.stops s on s.id = rs.stop_id
) c;

comment on view public.v_trip_stop_eta is
  'Deterministic per-stop ETA for in-progress trips. Distance / speed arithmetic plus a fixed dwell allowance - no model inference.';

-- -----------------------------------------------------------------------------
-- fn_trip_eta_minutes: scalar ETA lookup for one trip/stop pair.
-- -----------------------------------------------------------------------------
create or replace function public.fn_trip_eta_minutes(
  p_trip_id uuid,
  p_stop_id uuid
) returns integer
language sql
stable
as $$
  select e.eta_minutes
  from public.v_trip_stop_eta e
  where e.trip_id = p_trip_id
    and e.stop_id = p_stop_id
  order by e.stop_order
  limit 1;
$$;

comment on function public.fn_trip_eta_minutes is
  'Minutes until the given live trip reaches the given stop. Null if the trip is not running or the stop is already passed.';

-- -----------------------------------------------------------------------------
-- fn_stop_arrivals: next buses arriving at a stop (passenger "when is my bus").
-- -----------------------------------------------------------------------------
create or replace function public.fn_stop_arrivals(
  p_stop_id uuid,
  p_limit integer default 10
) returns table (
  trip_id              uuid,
  trip_code            text,
  route_code           text,
  route_name           text,
  route_color          text,
  bus_registration_no  text,
  eta_minutes          integer,
  estimated_arrival_at timestamptz,
  scheduled_arrival_at timestamptz,
  projected_delay_minutes integer
)
language sql
stable
as $$
  select
    e.trip_id,
    e.trip_code,
    e.route_code,
    r.name,
    r.color,
    b.registration_no,
    e.eta_minutes,
    e.estimated_arrival_at,
    e.scheduled_arrival_at,
    e.projected_delay_minutes
  from public.v_trip_stop_eta e
  join public.trips t on t.id = e.trip_id
  join public.routes r on r.id = e.route_id
  join public.buses b on b.id = t.bus_id
  where e.stop_id = p_stop_id
  order by e.eta_minutes
  limit greatest(coalesce(p_limit, 10), 1);
$$;

-- -----------------------------------------------------------------------------
-- fn_search_routes: direct routes from one stop to another.
-- Single-route journeys only; no transfer planning in the hackathon scope.
-- -----------------------------------------------------------------------------
create or replace function public.fn_search_routes(
  p_origin_stop_id      uuid,
  p_destination_stop_id uuid
) returns table (
  route_id                uuid,
  route_code              text,
  route_name              text,
  route_color             text,
  direction               public.trip_direction,
  origin_stop_order       integer,
  destination_stop_order  integer,
  intermediate_stops      integer,
  distance_km             numeric,
  estimated_duration_min  integer,
  fare_pkr                numeric,
  active_trip_count       integer,
  next_departure_at       timestamptz
)
language sql
stable
as $$
  select
    r.id,
    r.code,
    r.name,
    r.color,
    o.direction,
    o.stop_order,
    d.stop_order,
    (d.stop_order - o.stop_order - 1)::integer,
    round(d.distance_from_start_km - o.distance_from_start_km, 2),
    (d.scheduled_offset_min - o.scheduled_offset_min)::integer,
    r.fare_pkr,
    (
      select count(*)::integer
      from public.trips t
      where t.route_id = r.id
        and t.direction = o.direction
        and t.status = 'in_progress'
    ),
    (
      select min(t.scheduled_start_at + (o.scheduled_offset_min * interval '1 minute'))
      from public.trips t
      where t.route_id = r.id
        and t.direction = o.direction
        and t.status in ('scheduled', 'in_progress')
        and t.scheduled_start_at + (o.scheduled_offset_min * interval '1 minute') >= now()
    )
  from public.route_stops o
  join public.route_stops d
    on d.route_id = o.route_id
   and d.direction = o.direction
   and d.stop_order > o.stop_order
  join public.routes r on r.id = o.route_id
  where o.stop_id = p_origin_stop_id
    and d.stop_id = p_destination_stop_id
    and r.is_active
  order by (d.scheduled_offset_min - o.scheduled_offset_min),
           (d.distance_from_start_km - o.distance_from_start_km);
$$;

comment on function public.fn_search_routes is
  'Direct (no-transfer) routes serving origin -> destination, ordered by scheduled journey time.';

-- -----------------------------------------------------------------------------
-- fn_nearby_stops: stops within a radius, nearest first.
-- -----------------------------------------------------------------------------
create or replace function public.fn_nearby_stops(
  p_latitude   numeric,
  p_longitude  numeric,
  p_radius_km  numeric default 2,
  p_limit      integer default 10
) returns table (
  stop_id     uuid,
  code        text,
  name        text,
  area        text,
  latitude    numeric,
  longitude   numeric,
  distance_km numeric
)
language sql
stable
as $$
  select
    s.id,
    s.code,
    s.name,
    s.area,
    s.latitude,
    s.longitude,
    public.fn_haversine_km(p_latitude, p_longitude, s.latitude, s.longitude)
  from public.stops s
  where s.is_active
    and public.fn_haversine_km(p_latitude, p_longitude, s.latitude, s.longitude) <= coalesce(p_radius_km, 2)
  order by public.fn_haversine_km(p_latitude, p_longitude, s.latitude, s.longitude)
  limit greatest(coalesce(p_limit, 10), 1);
$$;

-- -----------------------------------------------------------------------------
-- v_route_summary: route list for passengers and the operator dashboard.
-- -----------------------------------------------------------------------------
create or replace view public.v_route_summary as
select
  r.id as route_id,
  r.code,
  r.name,
  r.description,
  r.color,
  r.distance_km,
  r.expected_duration_min,
  r.fare_pkr,
  r.headway_min,
  r.first_departure,
  r.last_departure,
  r.is_active,
  (select count(*) from public.route_stops rs
    where rs.route_id = r.id and rs.direction = 'outbound')::integer as outbound_stop_count,
  (select count(*) from public.route_stops rs
    where rs.route_id = r.id and rs.direction = 'inbound')::integer as inbound_stop_count,
  (select s.name from public.route_stops rs
     join public.stops s on s.id = rs.stop_id
    where rs.route_id = r.id and rs.direction = 'outbound'
    order by rs.stop_order asc limit 1) as origin_stop_name,
  (select s.name from public.route_stops rs
     join public.stops s on s.id = rs.stop_id
    where rs.route_id = r.id and rs.direction = 'outbound'
    order by rs.stop_order desc limit 1) as destination_stop_name,
  (select count(*) from public.trips t
    where t.route_id = r.id and t.status = 'in_progress')::integer as active_trip_count,
  (select count(*) from public.trips t
    where t.route_id = r.id and t.status = 'in_progress' and t.delay_minutes >= 5)::integer as delayed_trip_count
from public.routes r;

comment on view public.v_route_summary is 'Route catalogue with stop counts, endpoints and live trip counts.';

-- -----------------------------------------------------------------------------
-- v_fleet_overview: single-row KPI strip for the operator dashboard.
-- -----------------------------------------------------------------------------
create or replace view public.v_fleet_overview as
select
  (select count(*) from public.buses)::integer as total_buses,
  (select count(*) from public.buses where status = 'active')::integer as active_buses,
  (select count(*) from public.buses where status = 'idle')::integer as idle_buses,
  (select count(*) from public.buses where status = 'maintenance')::integer as maintenance_buses,
  (select count(*) from public.buses where status = 'offline')::integer as offline_buses,
  (select count(*) from public.routes where is_active)::integer as active_routes,
  (select count(*) from public.stops where is_active)::integer as active_stops,
  (select count(*) from public.trips where status = 'in_progress')::integer as trips_in_progress,
  (select count(*) from public.trips where status = 'in_progress' and delay_minutes >= 5)::integer as delayed_trips,
  (select count(*) from public.trips where status = 'scheduled' and scheduled_start_at >= now())::integer as upcoming_trips,
  (select coalesce(round(avg(delay_minutes), 1), 0) from public.trips where status = 'in_progress') as avg_delay_minutes,
  (select count(*) from public.service_alerts where is_active)::integer as active_alerts;

comment on view public.v_fleet_overview is 'Aggregate KPIs for the operator monitoring header.';


-- ===== supabase/migrations/20261001120200_rls_policies.sql =====
-- =============================================================================
-- Smart Public Transport & Bus Tracking Platform - Karachi
-- Migration 3/3: row level security, grants and view security mode
--
-- DEMO-GRADE SECURITY. The policies below are deliberately permissive: all
-- transport reference and live-tracking data is world-readable because the
-- passenger app is meant to work without logging in. This is not a production
-- security model - see docs/ASSUMPTIONS.md before reusing it.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Staff check. security definer so it can read profiles without tripping the
-- profiles policy (which would recurse).
-- -----------------------------------------------------------------------------
create or replace function public.fn_is_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.profiles p
    where p.auth_user_id = auth.uid()
      and p.role in ('operator', 'admin')
  );
$$;

-- -----------------------------------------------------------------------------
-- Enable RLS
-- -----------------------------------------------------------------------------
alter table public.profiles        enable row level security;
alter table public.drivers         enable row level security;
alter table public.buses           enable row level security;
alter table public.routes          enable row level security;
alter table public.stops           enable row level security;
alter table public.route_stops     enable row level security;
alter table public.trips           enable row level security;
alter table public.bus_locations   enable row level security;
alter table public.trip_stop_times enable row level security;
alter table public.service_alerts  enable row level security;

-- -----------------------------------------------------------------------------
-- profiles: a user sees and edits only their own row; staff see everything.
-- -----------------------------------------------------------------------------
create policy profiles_select_self_or_staff on public.profiles
  for select to authenticated
  using (auth_user_id = auth.uid() or public.fn_is_staff());

create policy profiles_insert_self on public.profiles
  for insert to authenticated
  with check (auth_user_id = auth.uid());

create policy profiles_update_self on public.profiles
  for update to authenticated
  using (auth_user_id = auth.uid())
  with check (auth_user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- drivers: personal data, so signed-in users only; staff can write.
-- -----------------------------------------------------------------------------
create policy drivers_select_authenticated on public.drivers
  for select to authenticated
  using (true);

create policy drivers_write_staff on public.drivers
  for all to authenticated
  using (public.fn_is_staff())
  with check (public.fn_is_staff());

-- -----------------------------------------------------------------------------
-- Public transport reference data: readable by everyone, writable by staff.
-- -----------------------------------------------------------------------------
create policy routes_select_public on public.routes
  for select to anon, authenticated using (true);
create policy routes_write_staff on public.routes
  for all to authenticated using (public.fn_is_staff()) with check (public.fn_is_staff());

create policy stops_select_public on public.stops
  for select to anon, authenticated using (true);
create policy stops_write_staff on public.stops
  for all to authenticated using (public.fn_is_staff()) with check (public.fn_is_staff());

create policy route_stops_select_public on public.route_stops
  for select to anon, authenticated using (true);
create policy route_stops_write_staff on public.route_stops
  for all to authenticated using (public.fn_is_staff()) with check (public.fn_is_staff());

create policy buses_select_public on public.buses
  for select to anon, authenticated using (true);
create policy buses_write_staff on public.buses
  for all to authenticated using (public.fn_is_staff()) with check (public.fn_is_staff());

create policy service_alerts_select_public on public.service_alerts
  for select to anon, authenticated using (true);
create policy service_alerts_write_staff on public.service_alerts
  for all to authenticated using (public.fn_is_staff()) with check (public.fn_is_staff());

-- -----------------------------------------------------------------------------
-- Live operational data: public read so the tracking map works logged-out.
-- Writes are limited to signed-in users; the location feed should really run
-- with the service_role key, which bypasses RLS entirely.
-- -----------------------------------------------------------------------------
create policy trips_select_public on public.trips
  for select to anon, authenticated using (true);
create policy trips_write_authenticated on public.trips
  for all to authenticated using (true) with check (true);

create policy bus_locations_select_public on public.bus_locations
  for select to anon, authenticated using (true);
create policy bus_locations_write_authenticated on public.bus_locations
  for all to authenticated using (true) with check (true);

create policy trip_stop_times_select_public on public.trip_stop_times
  for select to anon, authenticated using (true);
create policy trip_stop_times_write_authenticated on public.trip_stop_times
  for all to authenticated using (true) with check (true);

-- -----------------------------------------------------------------------------
-- Views run with the caller's permissions so the policies above still apply.
-- -----------------------------------------------------------------------------
alter view public.v_bus_latest_location set (security_invoker = on);
alter view public.v_fleet_status        set (security_invoker = on);
alter view public.v_active_trips        set (security_invoker = on);
alter view public.v_trip_stop_eta       set (security_invoker = on);
alter view public.v_route_summary       set (security_invoker = on);
alter view public.v_fleet_overview      set (security_invoker = on);

-- -----------------------------------------------------------------------------
-- Grants (RLS still filters rows; these just open the tables to the API roles).
-- -----------------------------------------------------------------------------
grant usage on schema public to anon, authenticated;

grant select on
  public.routes, public.stops, public.route_stops, public.buses,
  public.trips, public.bus_locations, public.trip_stop_times, public.service_alerts,
  public.v_bus_latest_location, public.v_fleet_status, public.v_active_trips,
  public.v_trip_stop_eta, public.v_route_summary, public.v_fleet_overview
to anon, authenticated;

grant select on public.profiles, public.drivers to authenticated;

grant insert, update, delete on
  public.profiles, public.drivers, public.routes, public.stops, public.route_stops,
  public.buses, public.trips, public.bus_locations, public.trip_stop_times,
  public.service_alerts
to authenticated;

grant usage, select on sequence public.bus_locations_id_seq to authenticated;

grant execute on function
  public.fn_haversine_km(numeric, numeric, numeric, numeric),
  public.fn_route_segments(uuid, public.trip_direction),
  public.fn_route_point_at_km(uuid, public.trip_direction, numeric),
  public.fn_trip_eta_minutes(uuid, uuid),
  public.fn_stop_arrivals(uuid, integer),
  public.fn_search_routes(uuid, uuid),
  public.fn_nearby_stops(numeric, numeric, numeric, integer)
to anon, authenticated;

-- -----------------------------------------------------------------------------
-- Demo escape hatch: if RLS blocks the demo and time is short, run this in the
-- Supabase SQL editor to drop straight to open access. Never ship it.
--
--   alter table public.profiles        disable row level security;
--   alter table public.drivers         disable row level security;
--   alter table public.buses           disable row level security;
--   alter table public.routes          disable row level security;
--   alter table public.stops           disable row level security;
--   alter table public.route_stops     disable row level security;
--   alter table public.trips           disable row level security;
--   alter table public.bus_locations   disable row level security;
--   alter table public.trip_stop_times disable row level security;
--   alter table public.service_alerts  disable row level security;
-- -----------------------------------------------------------------------------


-- ===== supabase/migrations/20261001130000_gps_freshness.sql =====
-- =============================================================================
-- Smart Public Transport & Bus Tracking Platform - Karachi
-- Migration 4: GPS freshness and ETA input exposure
--
-- Why this is a separate migration: migrations 1-3 are already committed and may
-- already be applied to the Supabase project, so they are treated as immutable.
--
-- What it adds:
--   * A GPS freshness signal on every live view, so the UI can say
--     "Location temporarily unavailable" instead of rendering a stale pin as if
--     it were live (required by demo scenario 4 / GPS_UNAVAILABLE).
--   * elapsed_minutes on v_active_trips, the one deterministic ETA input that
--     was previously only derivable by the caller.
--
-- Two deliberately different staleness thresholds, because they answer
-- different questions:
--   * 3 minutes  - passenger-facing: "is this pin safe to draw as live?"
--   * 10 minutes - operator-facing: "has this vehicle stopped reporting?"
--     (kept as v_fleet_status.telemetry_stale, unchanged)
--
-- No table changes. Views are replaced with columns appended at the end, which
-- is all CREATE OR REPLACE VIEW permits.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- v_active_trips: + elapsed_minutes, location_age, location_is_stale, gps_status
-- -----------------------------------------------------------------------------
create or replace view public.v_active_trips as
select
  t.id as trip_id,
  t.trip_code,
  t.status,
  t.direction,
  t.service_date,
  t.scheduled_start_at,
  t.scheduled_end_at,
  t.actual_start_at,
  t.delay_minutes,
  (t.delay_minutes >= 5) as is_delayed,
  t.progress_km,
  t.last_stop_order,
  t.occupancy,
  r.id as route_id,
  r.code as route_code,
  r.name as route_name,
  r.color as route_color,
  r.distance_km as route_distance_km,
  r.fare_pkr,
  case
    when r.distance_km > 0 then round(100 * t.progress_km / r.distance_km, 1)
    else 0
  end as progress_pct,
  b.id as bus_id,
  b.registration_no,
  b.label as bus_label,
  b.capacity,
  case
    when b.capacity > 0 then round(100.0 * t.occupancy / b.capacity, 1)
    else 0
  end as occupancy_pct,
  d.id as driver_id,
  d.full_name as driver_name,
  d.phone as driver_phone,
  ns.id as next_stop_id,
  ns.name as next_stop_name,
  l.latitude,
  l.longitude,
  l.speed_kmh,
  l.heading_deg,
  l.recorded_at as location_recorded_at,
  -- appended by migration 4
  round(extract(epoch from (now() - coalesce(t.actual_start_at, t.scheduled_start_at))) / 60.0)::integer
    as elapsed_minutes,
  (now() - l.recorded_at) as location_age,
  (l.recorded_at is null or l.recorded_at < now() - interval '3 minutes') as location_is_stale,
  case
    when l.recorded_at is null then 'no_fix'
    when l.recorded_at < now() - interval '3 minutes' then 'stale'
    else 'live'
  end as gps_status
from public.trips t
join public.routes r on r.id = t.route_id
join public.buses b on b.id = t.bus_id
left join public.drivers d on d.id = t.driver_id
left join public.stops ns on ns.id = t.next_stop_id
left join public.v_bus_latest_location l on l.bus_id = t.bus_id
where t.status = 'in_progress';

comment on view public.v_active_trips is
  'Live trips joined to route, bus, driver, next stop and latest GPS fix. Check gps_status before drawing the pin as live: live | stale | no_fix.';

-- -----------------------------------------------------------------------------
-- v_trip_stop_eta: + gps_status, so an arrivals board can mark or suppress an
-- ETA that was computed from an old position rather than presenting it as live.
-- -----------------------------------------------------------------------------
create or replace view public.v_trip_stop_eta as
select
  c.trip_id,
  c.trip_code,
  c.route_id,
  c.route_code,
  c.direction,
  c.stop_id,
  c.stop_code,
  c.stop_name,
  c.stop_order,
  c.latitude,
  c.longitude,
  c.distance_from_start_km,
  c.remaining_km,
  c.effective_speed_kmh,
  c.stops_ahead,
  c.eta_minutes,
  (now() + (c.eta_minutes * interval '1 minute')) as estimated_arrival_at,
  c.scheduled_arrival_at,
  round(
    extract(epoch from (now() + (c.eta_minutes * interval '1 minute')) - c.scheduled_arrival_at) / 60.0
  )::integer as projected_delay_minutes,
  -- appended by migration 4
  c.gps_status
from (
  select
    live.trip_id,
    live.trip_code,
    live.route_id,
    live.route_code,
    live.direction,
    live.gps_status,
    s.id   as stop_id,
    s.code as stop_code,
    s.name as stop_name,
    s.latitude,
    s.longitude,
    rs.stop_order,
    rs.distance_from_start_km,
    greatest(rs.distance_from_start_km - live.progress_km, 0) as remaining_km,
    live.effective_speed_kmh,
    (rs.stop_order - coalesce(live.last_stop_order, 0)) as stops_ahead,
    ceil(
      (greatest(rs.distance_from_start_km - live.progress_km, 0) / live.effective_speed_kmh) * 60
      + greatest(rs.stop_order - coalesce(live.last_stop_order, 0) - 1, 0) * 0.5
    )::integer as eta_minutes,
    live.scheduled_start_at + (rs.scheduled_offset_min * interval '1 minute') as scheduled_arrival_at
  from (
    select
      t.id as trip_id,
      t.trip_code,
      t.route_id,
      t.direction,
      t.progress_km,
      t.last_stop_order,
      t.scheduled_start_at,
      r.code as route_code,
      coalesce(nullif(l.speed_kmh, 0), r.avg_speed_kmh) as effective_speed_kmh,
      case
        when l.recorded_at is null then 'no_fix'
        when l.recorded_at < now() - interval '3 minutes' then 'stale'
        else 'live'
      end as gps_status
    from public.trips t
    join public.routes r on r.id = t.route_id
    left join public.v_bus_latest_location l on l.bus_id = t.bus_id
    where t.status = 'in_progress'
  ) live
  join public.route_stops rs
    on rs.route_id = live.route_id
   and rs.direction = live.direction
   and rs.stop_order > coalesce(live.last_stop_order, 0)
  join public.stops s on s.id = rs.stop_id
) c;

comment on view public.v_trip_stop_eta is
  'Deterministic per-stop ETA for in-progress trips. Distance / speed arithmetic plus a fixed dwell allowance - no model inference. When gps_status is not live the estimate is extrapolated from an old fix: label it, do not present it as live.';

-- -----------------------------------------------------------------------------
-- v_fleet_status: + gps_status alongside the existing 10-minute telemetry_stale
-- -----------------------------------------------------------------------------
create or replace view public.v_fleet_status as
select
  b.id as bus_id,
  b.registration_no,
  b.label as bus_label,
  b.status as bus_status,
  b.capacity,
  d.id   as driver_id,
  d.full_name as driver_name,
  t.id   as trip_id,
  t.trip_code,
  t.status as trip_status,
  r.id   as route_id,
  r.code as route_code,
  r.name as route_name,
  r.color as route_color,
  t.delay_minutes,
  coalesce(t.delay_minutes, 0) >= 5 as is_delayed,
  t.progress_km,
  l.latitude,
  l.longitude,
  l.speed_kmh,
  l.heading_deg,
  l.recorded_at as location_recorded_at,
  l.location_age,
  (l.recorded_at is null or l.recorded_at < now() - interval '10 minutes') as telemetry_stale,
  -- appended by migration 4
  case
    when l.recorded_at is null then 'no_fix'
    when l.recorded_at < now() - interval '3 minutes' then 'stale'
    else 'live'
  end as gps_status
from public.buses b
left join public.drivers d on d.id = b.assigned_driver_id
left join public.trips t on t.bus_id = b.id and t.status = 'in_progress'
left join public.routes r on r.id = t.route_id
left join public.v_bus_latest_location l on l.bus_id = b.id;

comment on view public.v_fleet_status is
  'One row per bus with its live trip (if any) and latest fix. telemetry_stale (10 min) means the vehicle has stopped reporting; gps_status (3 min) means the pin is not safe to draw as live.';

-- -----------------------------------------------------------------------------
-- fn_stop_arrivals: + gps_status. Dropped and recreated because CREATE OR
-- REPLACE FUNCTION cannot change a return type.
-- -----------------------------------------------------------------------------
drop function if exists public.fn_stop_arrivals(uuid, integer);

create function public.fn_stop_arrivals(
  p_stop_id uuid,
  p_limit integer default 10
) returns table (
  trip_id                 uuid,
  trip_code               text,
  route_code              text,
  route_name              text,
  route_color             text,
  bus_registration_no     text,
  eta_minutes             integer,
  estimated_arrival_at    timestamptz,
  scheduled_arrival_at    timestamptz,
  projected_delay_minutes integer,
  gps_status              text
)
language sql
stable
as $$
  select
    e.trip_id,
    e.trip_code,
    e.route_code,
    r.name,
    r.color,
    b.registration_no,
    e.eta_minutes,
    e.estimated_arrival_at,
    e.scheduled_arrival_at,
    e.projected_delay_minutes,
    e.gps_status
  from public.v_trip_stop_eta e
  join public.trips t on t.id = e.trip_id
  join public.routes r on r.id = e.route_id
  join public.buses b on b.id = t.bus_id
  where e.stop_id = p_stop_id
  order by e.eta_minutes
  limit greatest(coalesce(p_limit, 10), 1);
$$;

comment on function public.fn_stop_arrivals is
  'Next buses arriving at a stop, soonest first. Rows where gps_status is not live are extrapolated from an old fix.';

grant execute on function public.fn_stop_arrivals(uuid, integer) to anon, authenticated;

alter view public.v_active_trips  set (security_invoker = on);
alter view public.v_trip_stop_eta set (security_invoker = on);
alter view public.v_fleet_status  set (security_invoker = on);


-- ===== supabase/migrations/20261001140000_auth_and_realtime.sql =====
-- =============================================================================
-- Smart Public Transport & Bus Tracking Platform - Karachi
-- Migration 5: auth profile linking and realtime publication
--
-- Both sections are guarded so this file is safe to run anywhere:
--   * on Supabase it wires up auth.users and supabase_realtime
--   * on a plain Postgres (the validation harness) it skips those parts with a
--     notice instead of failing
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Profile creation / linking on sign-up
--
-- Makes `role` available to the application immediately after sign-in:
--   * if a profile already exists with the same email and no auth link (the
--     demo rows from seed.sql), adopt it and keep its role
--   * otherwise create a profile, taking the role from sign-up metadata
--
-- security definer so it can write to profiles regardless of RLS.
-- -----------------------------------------------------------------------------
create or replace function public.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_requested text := new.raw_user_meta_data ->> 'role';
  v_role public.user_role := 'passenger';
begin
  -- Only accept a role we recognise; never cast unvalidated text to the enum.
  if v_requested in ('passenger', 'driver', 'operator', 'admin') then
    v_role := v_requested::public.user_role;
  end if;

  update public.profiles p
  set auth_user_id = new.id,
      role = case when v_requested is null then p.role else v_role end
  where p.email = new.email
    and p.auth_user_id is null;

  if not found then
    insert into public.profiles (auth_user_id, full_name, email, role)
    values (
      new.id,
      coalesce(
        new.raw_user_meta_data ->> 'full_name',
        split_part(coalesce(new.email, 'user'), '@', 1)
      ),
      new.email,
      v_role
    )
    on conflict (auth_user_id) do nothing;
  end if;

  return new;
end;
$$;

comment on function public.handle_new_auth_user is
  'Trigger on auth.users: adopts a matching demo profile by email, otherwise creates one with the role from sign-up metadata.';

do $$
begin
  if exists (
    select 1 from information_schema.tables
    where table_schema = 'auth' and table_name = 'users'
  ) then
    execute 'drop trigger if exists on_auth_user_created on auth.users';
    execute 'create trigger on_auth_user_created
               after insert on auth.users
               for each row execute function public.handle_new_auth_user()';
    raise notice 'Installed on_auth_user_created trigger on auth.users';
  else
    raise notice 'auth.users not found - skipping sign-up trigger (not a Supabase instance)';
  end if;
end
$$;

-- -----------------------------------------------------------------------------
-- 2. Realtime
--
-- bus_locations is the live feed: the driver inserts a fix, passengers and the
-- operator receive it. trips carries status and delay changes; service_alerts
-- carries announcements.
--
-- trips gets REPLICA IDENTITY FULL so UPDATE events include the previous row,
-- which lets a client diff a status or delay change. bus_locations is
-- insert-only, so the default replica identity is enough.
-- -----------------------------------------------------------------------------
alter table public.trips replica identity full;

do $$
declare
  v_table text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    raise notice 'supabase_realtime publication not found - skipping realtime setup (not a Supabase instance)';
    return;
  end if;

  foreach v_table in array array['bus_locations', 'trips', 'service_alerts']
  loop
    if exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = v_table
    ) then
      raise notice 'public.% already in supabase_realtime', v_table;
    else
      execute format('alter publication supabase_realtime add table public.%I', v_table);
      raise notice 'Added public.% to supabase_realtime', v_table;
    end if;
  end loop;
end
$$;


-- ===== supabase/migrations/20261001150000_trip_control.sql =====
-- =============================================================================
-- Trip lifecycle + deterministic GPS simulation
--
-- DEMO / SIMULATED HACKATHON DATA. The simulation moves a bus along the
-- straight lines between its configured stops. It is not road-snapped and makes
-- no claim to model real traffic.
--
-- Everything the driver app does is one function call so the write is atomic:
-- location fix, trip progress, next stop and stop arrivals move together, and
-- the realtime event the passenger receives is never half-applied.
--
-- No ML. Progress is distance = speed x time, and position is linear
-- interpolation along the route via fn_route_point_at_km.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- v_trip_live: everything a tracking screen needs, for trips in ANY state.
--
-- v_active_trips deliberately filters to in_progress. A passenger who has a
-- tracking page open when the driver ends the trip still needs a row back, so
-- this view covers every status and exposes a single operational_state that the
-- UI can switch on.
-- -----------------------------------------------------------------------------
create or replace view public.v_trip_live as
with latest as (
  select
    l.bus_id,
    l.latitude,
    l.longitude,
    l.speed_kmh,
    l.heading_deg,
    l.recorded_at,
    l.source
  from public.v_bus_latest_location l
)
select
  t.id as trip_id,
  t.trip_code,
  t.status,
  t.direction,
  t.service_date,
  t.scheduled_start_at,
  t.scheduled_end_at,
  t.actual_start_at,
  t.actual_end_at,
  t.delay_minutes,
  (t.delay_minutes >= 5) as is_delayed,
  t.progress_km,
  t.last_stop_order,
  t.occupancy,
  r.id as route_id,
  r.code as route_code,
  r.name as route_name,
  r.color as route_color,
  r.distance_km as route_distance_km,
  r.expected_duration_min,
  r.avg_speed_kmh,
  r.fare_pkr,
  case
    when r.distance_km > 0 then round(100 * t.progress_km / r.distance_km, 1)
    else 0
  end as progress_pct,
  b.id as bus_id,
  b.registration_no,
  b.label as bus_label,
  b.capacity,
  b.status as bus_status,
  d.id as driver_id,
  d.full_name as driver_name,
  ns.id as next_stop_id,
  ns.name as next_stop_name,
  ns.latitude as next_stop_latitude,
  ns.longitude as next_stop_longitude,
  l.latitude,
  l.longitude,
  l.speed_kmh,
  l.heading_deg,
  l.recorded_at as location_recorded_at,
  l.source as location_source,
  case
    when l.recorded_at is null then null
    else round(extract(epoch from (now() - l.recorded_at)) / 60.0, 2)
  end as location_age_minutes,
  -- A fix older than 3 minutes is not live. The UI must not plot it as current.
  case
    when l.recorded_at is null then 'no_fix'
    when now() - l.recorded_at > interval '3 minutes' then 'stale'
    else 'live'
  end as gps_status,
  -- Single operational state for the UI. GPS trust comes first: if we cannot
  -- vouch for the position, "stopped" and "on time" are both unsupportable.
  case
    when t.status = 'completed' then 'COMPLETED'
    when t.status = 'cancelled' then 'CANCELLED'
    when t.status = 'scheduled' then 'SCHEDULED'
    when l.recorded_at is null
      or now() - l.recorded_at > interval '3 minutes' then 'GPS_UNAVAILABLE'
    when coalesce(l.speed_kmh, 0) = 0 then 'STOPPED'
    when t.delay_minutes >= 5 then 'DELAYED'
    else 'ON_TIME'
  end as operational_state
from public.trips t
join public.routes r on r.id = t.route_id
join public.buses b on b.id = t.bus_id
left join public.drivers d on d.id = t.driver_id
left join public.stops ns on ns.id = t.next_stop_id
left join latest l on l.bus_id = t.bus_id;

comment on view public.v_trip_live is
  'Per-trip live state for any status, with a derived operational_state (SCHEDULED/ON_TIME/DELAYED/STOPPED/GPS_UNAVAILABLE/COMPLETED/CANCELLED).';

-- -----------------------------------------------------------------------------
-- fn_trip_sync_position: shared bookkeeping after progress changes.
--
-- Keeps last_stop_order, next_stop_id and trip_stop_times consistent with
-- progress_km. Called by both the simulator and the real-GPS path so the two
-- can never drift apart.
-- -----------------------------------------------------------------------------
create or replace function public.fn_trip_sync_position(
  p_trip_id uuid,
  p_progress_km numeric
) returns void
language plpgsql
as $$
declare
  v_trip   record;
  v_last   integer;
  v_next   uuid;
begin
  select t.*, r.distance_km
    into v_trip
  from public.trips t
  join public.routes r on r.id = t.route_id
  where t.id = p_trip_id;

  if not found then
    raise exception 'Trip % not found', p_trip_id using errcode = 'no_data_found';
  end if;

  -- Highest stop already passed, and the first one still ahead.
  select max(rs.stop_order)
    into v_last
  from public.route_stops rs
  where rs.route_id = v_trip.route_id
    and rs.direction = v_trip.direction
    and rs.distance_from_start_km <= p_progress_km;

  select rs.stop_id
    into v_next
  from public.route_stops rs
  where rs.route_id = v_trip.route_id
    and rs.direction = v_trip.direction
    and rs.distance_from_start_km > p_progress_km
  order by rs.stop_order asc
  limit 1;

  update public.trips
  set progress_km     = p_progress_km,
      last_stop_order = coalesce(v_last, 0),
      next_stop_id    = v_next
  where id = p_trip_id;

  -- Stamp arrivals for stops we have now reached.
  update public.trip_stop_times tst
  set status            = 'arrived',
      actual_arrival_at = now()
  where tst.trip_id = p_trip_id
    and tst.status = 'pending'
    and tst.stop_order <= coalesce(v_last, 0);
end;
$$;

-- -----------------------------------------------------------------------------
-- fn_start_trip: SCHEDULED -> IN_PROGRESS.
--
-- Refuses to start a trip that is not scheduled, and refuses to give a bus a
-- second concurrent trip.
-- -----------------------------------------------------------------------------
create or replace function public.fn_start_trip(p_trip_id uuid)
returns uuid
language plpgsql
as $$
declare
  v_trip     record;
  v_conflict text;
  v_point    record;
begin
  select * into v_trip from public.trips where id = p_trip_id for update;

  if not found then
    raise exception 'Trip % not found', p_trip_id using errcode = 'no_data_found';
  end if;

  if v_trip.status = 'in_progress' then
    return v_trip.id; -- idempotent: already running
  end if;

  if v_trip.status <> 'scheduled' then
    raise exception 'Cannot start trip %: status is %, expected scheduled', v_trip.trip_code, v_trip.status
      using errcode = 'check_violation';
  end if;

  select t.trip_code into v_conflict
  from public.trips t
  where t.bus_id = v_trip.bus_id
    and t.status = 'in_progress'
    and t.id <> v_trip.id
  limit 1;

  if v_conflict is not null then
    raise exception 'Bus already has trip % in progress', v_conflict
      using errcode = 'check_violation';
  end if;

  update public.trips
  set status          = 'in_progress',
      actual_start_at = now(),
      actual_end_at   = null,
      progress_km     = 0
  where id = p_trip_id;

  update public.buses set status = 'active' where id = v_trip.bus_id;

  perform public.fn_trip_sync_position(p_trip_id, 0);

  -- Opening fix at the origin so the passenger map has something immediately.
  select * into v_point
  from public.fn_route_point_at_km(v_trip.route_id, v_trip.direction, 0);

  if v_point.latitude is not null then
    insert into public.bus_locations
      (bus_id, trip_id, recorded_at, latitude, longitude, speed_kmh, heading_deg, progress_km, source)
    values
      (v_trip.bus_id, p_trip_id, now(), v_point.latitude, v_point.longitude, 0, v_point.heading_deg, 0, 'simulated');
  end if;

  return p_trip_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- fn_end_trip: IN_PROGRESS -> COMPLETED.
-- -----------------------------------------------------------------------------
create or replace function public.fn_end_trip(p_trip_id uuid)
returns uuid
language plpgsql
as $$
declare
  v_trip     record;
  v_distance numeric;
  v_maxorder integer;
begin
  select t.*, r.distance_km
    into v_trip
  from public.trips t
  join public.routes r on r.id = t.route_id
  where t.id = p_trip_id
  for update of t;

  if not found then
    raise exception 'Trip % not found', p_trip_id using errcode = 'no_data_found';
  end if;

  if v_trip.status = 'completed' then
    return p_trip_id; -- idempotent
  end if;

  if v_trip.status <> 'in_progress' then
    raise exception 'Cannot end trip %: status is %, expected in_progress', v_trip.trip_code, v_trip.status
      using errcode = 'check_violation';
  end if;

  v_distance := v_trip.distance_km;

  select max(rs.stop_order) into v_maxorder
  from public.route_stops rs
  where rs.route_id = v_trip.route_id
    and rs.direction = v_trip.direction;

  update public.trips
  set status          = 'completed',
      actual_end_at   = now(),
      progress_km     = v_distance,
      last_stop_order = v_maxorder,
      next_stop_id    = null
  where id = p_trip_id;

  update public.trip_stop_times
  set status            = 'arrived',
      actual_arrival_at = coalesce(actual_arrival_at, now())
  where trip_id = p_trip_id
    and status = 'pending';

  -- Free the bus unless it is out of service.
  update public.buses
  set status = 'idle'
  where id = v_trip.bus_id
    and status = 'active';

  return p_trip_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- fn_advance_trip: one deterministic simulation tick.
--
--   delta_km     = speed_kmh * tick_seconds / 3600
--   new_progress = min(progress + delta_km, route distance)
--
-- Position comes from fn_route_point_at_km, so the bus always sits exactly on
-- the configured route. Auto-completes on arrival at the final stop.
-- -----------------------------------------------------------------------------
create or replace function public.fn_advance_trip(
  p_trip_id       uuid,
  p_tick_seconds  numeric default 5,
  p_speed_kmh     numeric default null
) returns uuid
language plpgsql
as $$
declare
  v_trip     record;
  v_speed    numeric;
  v_delta    numeric;
  v_progress numeric;
  v_point    record;
begin
  select t.*, r.distance_km, r.avg_speed_kmh
    into v_trip
  from public.trips t
  join public.routes r on r.id = t.route_id
  where t.id = p_trip_id;

  if not found then
    raise exception 'Trip % not found', p_trip_id using errcode = 'no_data_found';
  end if;

  if v_trip.status <> 'in_progress' then
    raise exception 'Cannot advance trip %: status is %, expected in_progress', v_trip.trip_code, v_trip.status
      using errcode = 'check_violation';
  end if;

  -- A caller-supplied 0 is meaningful (bus halted), so only fall back on NULL.
  v_speed := coalesce(p_speed_kmh, v_trip.avg_speed_kmh);
  v_delta := v_speed * coalesce(p_tick_seconds, 5) / 3600.0;

  v_progress := least(v_trip.progress_km + v_delta, v_trip.distance_km);

  select * into v_point
  from public.fn_route_point_at_km(v_trip.route_id, v_trip.direction, v_progress);

  if v_point.latitude is null then
    raise exception 'Route % has no geometry for direction %', v_trip.route_id, v_trip.direction;
  end if;

  insert into public.bus_locations
    (bus_id, trip_id, recorded_at, latitude, longitude, speed_kmh, heading_deg, progress_km, source)
  values
    (v_trip.bus_id, p_trip_id, now(), v_point.latitude, v_point.longitude,
     round(v_speed, 2), v_point.heading_deg, round(v_progress, 3), 'simulated');

  perform public.fn_trip_sync_position(p_trip_id, v_progress);

  if v_progress >= v_trip.distance_km then
    perform public.fn_end_trip(p_trip_id);
  end if;

  return p_trip_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- fn_record_trip_location: real browser GPS.
--
-- Progress is snapped to the nearest stop on the route and never allowed to go
-- backwards, which keeps ETA monotonic without needing real map matching.
-- -----------------------------------------------------------------------------
create or replace function public.fn_record_trip_location(
  p_trip_id     uuid,
  p_latitude    numeric,
  p_longitude   numeric,
  p_speed_kmh   numeric default 0,
  p_heading_deg numeric default null
) returns uuid
language plpgsql
as $$
declare
  v_trip     record;
  v_snapped  numeric;
  v_progress numeric;
begin
  if p_latitude is null or p_longitude is null
     or p_latitude < -90 or p_latitude > 90
     or p_longitude < -180 or p_longitude > 180 then
    raise exception 'Invalid coordinates: %, %', p_latitude, p_longitude
      using errcode = 'check_violation';
  end if;

  select t.*, r.distance_km
    into v_trip
  from public.trips t
  join public.routes r on r.id = t.route_id
  where t.id = p_trip_id;

  if not found then
    raise exception 'Trip % not found', p_trip_id using errcode = 'no_data_found';
  end if;

  if v_trip.status <> 'in_progress' then
    raise exception 'Cannot record location for trip %: status is %', v_trip.trip_code, v_trip.status
      using errcode = 'check_violation';
  end if;

  select rs.distance_from_start_km
    into v_snapped
  from public.route_stops rs
  join public.stops s on s.id = rs.stop_id
  where rs.route_id = v_trip.route_id
    and rs.direction = v_trip.direction
  order by public.fn_haversine_km(p_latitude, p_longitude, s.latitude, s.longitude) asc
  limit 1;

  v_progress := least(greatest(coalesce(v_snapped, 0), v_trip.progress_km), v_trip.distance_km);

  insert into public.bus_locations
    (bus_id, trip_id, recorded_at, latitude, longitude, speed_kmh, heading_deg, progress_km, source)
  values
    (v_trip.bus_id, p_trip_id, now(), p_latitude, p_longitude,
     round(coalesce(p_speed_kmh, 0), 2), p_heading_deg, round(v_progress, 3), 'device');

  perform public.fn_trip_sync_position(p_trip_id, v_progress);

  return p_trip_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- fn_set_trip_delay: operator/demo delay control.
--
-- Delay is stored on the trip; v_trip_live turns >= 5 min into DELAYED and
-- v_trip_stop_eta adds it to every downstream projection.
-- -----------------------------------------------------------------------------
create or replace function public.fn_set_trip_delay(
  p_trip_id       uuid,
  p_delay_minutes integer
) returns uuid
language plpgsql
as $$
begin
  if p_delay_minutes is null or p_delay_minutes < 0 or p_delay_minutes > 240 then
    raise exception 'Delay must be between 0 and 240 minutes, got %', p_delay_minutes
      using errcode = 'check_violation';
  end if;

  update public.trips
  set delay_minutes = p_delay_minutes
  where id = p_trip_id;

  if not found then
    raise exception 'Trip % not found', p_trip_id using errcode = 'no_data_found';
  end if;

  return p_trip_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- fn_route_path: ordered polyline for drawing a route on the map.
-- -----------------------------------------------------------------------------
create or replace function public.fn_route_path(
  p_route_id  uuid,
  p_direction public.trip_direction default 'outbound'
) returns table (
  stop_order             integer,
  stop_id                uuid,
  stop_code              text,
  stop_name              text,
  latitude               numeric,
  longitude              numeric,
  distance_from_start_km numeric,
  is_major_stop          boolean
)
language sql
stable
as $$
  select
    rs.stop_order,
    s.id,
    s.code,
    s.name,
    s.latitude,
    s.longitude,
    rs.distance_from_start_km,
    rs.is_major_stop
  from public.route_stops rs
  join public.stops s on s.id = rs.stop_id
  where rs.route_id = p_route_id
    and rs.direction = p_direction
  order by rs.stop_order;
$$;

comment on function public.fn_route_path is 'Ordered stops for a route direction, used as the map polyline.';

-- -----------------------------------------------------------------------------
-- Access. Reads stay public (demo data); state changes are server-side only.
-- Guarded so the migration also runs on a plain Postgres without Supabase roles.
-- -----------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    grant select on public.v_trip_live to anon, authenticated;
    grant execute on function public.fn_route_path(uuid, public.trip_direction) to anon, authenticated;
  end if;

  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant select on public.v_trip_live to service_role;
    grant execute on function public.fn_start_trip(uuid) to service_role;
    grant execute on function public.fn_end_trip(uuid) to service_role;
    grant execute on function public.fn_advance_trip(uuid, numeric, numeric) to service_role;
    grant execute on function public.fn_record_trip_location(uuid, numeric, numeric, numeric, numeric) to service_role;
    grant execute on function public.fn_set_trip_delay(uuid, integer) to service_role;
    grant execute on function public.fn_route_path(uuid, public.trip_direction) to service_role;
  end if;
end;
$$;

alter view public.v_trip_live set (security_invoker = on);


-- ===== supabase/seed.sql =====
-- =============================================================================
-- Smart Public Transport & Bus Tracking Platform - Karachi
-- DEMO SEED DATA
--
-- ##########################################################################
-- # EVERYTHING BELOW IS SIMULATED HACKATHON DATA.                          #
-- # The corridors, timetables, fares, headways, bus registrations, drivers #
-- # and passengers are INVENTED. They do not describe any real Karachi bus #
-- # service, operator, schedule or fare. Stop coordinates are approximate  #
-- # positions of real, well-known Karachi landmarks so the map renders      #
-- # believably - the stops themselves are demo constructs.                 #
-- ##########################################################################
--
-- The script is idempotent: it truncates the demo tables and reloads them, so
-- it can be re-run to refresh the "live" timestamps before a demo.
--
-- All trip times are generated relative to now(), so there is always at least
-- one in-progress trip, one delayed bus and one offline bus whenever you run it.
-- =============================================================================

begin;

truncate table
  public.bus_locations,
  public.trip_stop_times,
  public.trips,
  public.service_alerts,
  public.route_stops,
  public.buses,
  public.drivers,
  public.stops,
  public.routes,
  public.profiles
restart identity cascade;

